final readonly class TransferService
{
    public function __construct(private EntityManagerInterface $em)
    {
    }

    public function send(int $fromId, int $toId, int $amount): Transfer
    {
        return $this->em->wrapInTransaction(function () use ($fromId, $toId, $amount) {
            $ids = [$fromId, $toId];
            sort($ids);                 // always lock the smaller id first
            $wallets = [];
            foreach ($ids as $id) {
                $wallets[$id] = $this->em->find(Wallet::class, $id, LockMode::PESSIMISTIC_WRITE)
                    ?? throw new WalletNotFound($id);
            }

            $wallets[$fromId]->withdraw($amount);   // throws if the balance is too low
            $wallets[$toId]->deposit($amount);

            $transfer = new Transfer($wallets[$fromId], $wallets[$toId], $amount);
            $this->em->persist($transfer);

            return $transfer;           // then flush() and COMMIT happen on their own
        });
    }
}

