final readonly class SerializableRunner
{
    public function __construct(private Connection $connection)
    {
    }

    /** @param \Closure(Connection): mixed $work */
    public function run(\Closure $work, int $maxAttempts = 3): mixed
    {
        for ($attempt = 1; ; ++$attempt) {
            try {
                return $this->connection->transactional(function (Connection $c) use ($work) {
                    // PostgreSQL: for this transaction only, before the first query
                    $c->executeStatement('SET TRANSACTION ISOLATION LEVEL SERIALIZABLE');

                    return $work($c);
                });
            } catch (RetryableException $e) {   // serialization failure or deadlock
                if ($attempt >= $maxAttempts) {
                    throw $e;
                }
                usleep(random_int(5_000, 30_000) * $attempt);   // pause briefly, retry
            }
        }
    }
}

