use Doctrine\DBAL\LockMode;

public function send(int $walletId, int $amount): void
{
    $this->em->wrapInTransaction(function () use ($walletId, $amount): void {
        $wallet = $this->em->find(Wallet::class, $walletId, LockMode::PESSIMISTIC_WRITE)
            ?? throw new WalletNotFound($walletId);

        // a balance read after the lock can no longer be stale
        if ($wallet->getBalance() < $amount) {
            throw new InsufficientFunds();
        }

        $wallet->withdraw($amount);
    });   // the lock is released on COMMIT
}

