public function export(string $month): void
{
    $lock = $this->lockFactory->createLock('invoice-export-'.$month, ttl: 120);

    if (!$lock->acquire()) {
        throw new ExportAlreadyRunning($month);   // someone else is running it
    }

    try {
        foreach ($this->batches($month) as $batch) {
            $this->write($batch);
            $lock->refresh();     // TTL back to 120 seconds
        }
    } finally {
        $lock->release();
    }
}

