CREATE UNIQUE INDEX one_active_reservation
    ON reservation (seat_id) WHERE status IN ('held', 'confirmed');

public function hold(int $seatId, int $userId): Reservation
{
    $now = $this->clock->now();

    try {
        return $this->em->wrapInTransaction(function () use ($seatId, $userId, $now) {
            // clear out stale holds first, or the seat stays blocked forever
            $this->em->createQuery(
                "UPDATE App\Entity\Reservation r SET r.status = 'expired'
                 WHERE r.seatId = :seat AND r.status = 'held' AND r.expiresAt <= :now"
            )->setParameter('seat', $seatId)->setParameter('now', $now)->execute();

            $r = new Reservation($seatId, $userId, $now->modify('+10 minutes'));
            $this->em->persist($r);

            return $r;   // the unique index is checked as soon as flush() runs
        });
    } catch (UniqueConstraintViolationException) {
        throw new SeatTaken($seatId);   // someone else holds or has booked it
    }
}

public function confirm(int $reservationId): void
{
    $confirmed = $this->em->createQuery(
        "UPDATE App\Entity\Reservation r SET r.status = 'confirmed'
         WHERE r.id = :id AND r.status = 'held' AND r.expiresAt > :now"
    )
        ->setParameter('id', $reservationId)
        ->setParameter('now', $this->clock->now())
        ->execute();

    if ($confirmed === 0) {
        throw new HoldExpired($reservationId);   // refund, or try again from scratch
    }
}

