#[AsMessageHandler]
final readonly class PaymentSucceededHandler
{
    public function __construct(
        private SeatHolder $holder,
        private PaymentGateway $gateway,
        private NotifierInterface $notifier,
    ) {
    }

    public function __invoke(PaymentSucceeded $event): void
    {
        try {
            $this->holder->confirm($event->reservationId);
        } catch (HoldExpired) {
            // the seat is gone: refund, keyed by payment id so a retry can't refund twice
            $this->gateway->refund(
                $event->paymentId,
                idempotencyKey: 'refund-'.$event->paymentId,
            );
            $this->notifier->send(
                new SeatLostNotification($event->reservationId),
                $event->recipient,
            );
        }
    }
}

