public function place(PlaceOrder $cmd): Order
{
    return $this->em->wrapInTransaction(function () use ($cmd): Order {
        $order = Order::place($cmd->customerId, $cmd->items);
        $this->em->persist($order);

        // same transaction: order and message commit together, or neither does
        $this->em->persist(new OutboxMessage(
