}

#[AsPeriodicTask(frequency: '5 seconds')]
final readonly class OutboxRelay
{
    public function __invoke(): void
    {
        $this->em->wrapInTransaction(function (): void {
            $rows = $this->em->getConnection()->fetchAllAssociative(
                'SELECT id, type, payload FROM outbox_message
                 WHERE published_at IS NULL ORDER BY created_at
                 LIMIT 100 FOR UPDATE SKIP LOCKED'
            );
            foreach ($rows as $row) {
                $this->bus->dispatch(
                    new PublishEvent($row['id'], $row['type'], $row['payload'])
                );
                $this->em->getConnection()->executeStatement(
                    'UPDATE outbox_message SET published_at = NOW() WHERE id = :id',
                    ['id' => $row['id']],
                );
            }
        });
    }
}

public function run(string $sagaId, PlaceOrder $cmd): void
{
    foreach ($this->steps as $step) {       // order, payment, stock, courier
        try {
            $step->execute($sagaId, $cmd);  // the saga id is the idempotency key
        } catch (\Throwable) {
            $this->sagas->markCompensating($sagaId);
            $this->bus->dispatch(new CompensateNext($sagaId));

            return;
        }
        $this->sagas->recordDone($sagaId, $step::class);
    }
    $this->sagas->markCompleted($sagaId);
}

#[AsMessageHandler]
final readonly class CompensateNextHandler
{
    public function __invoke(CompensateNext $m): void
    {
        $stepClass = $this->sagas->lastDoneStep($m->sagaId);  // 3, then 2, then 1
        if ($stepClass === null) {
            $this->sagas->markCanceled($m->sagaId);          // all undone
            return;
        }

        // refund, release the hold... if this throws, Messenger retries the message
        $this->steps->get($stepClass)->compensate($m->sagaId);

        $this->sagas->removeDone($m->sagaId, $stepClass);
        $this->bus->dispatch(new CompensateNext($m->sagaId));
    }
}

