        $this->em->wrapInTransaction(function () use ($event): void {
            $fresh = $this->em->getConnection()->executeStatement(
                'INSERT INTO processed_message (message_id, handler)
                 VALUES (:id, :h) ON CONFLICT DO NOTHING',
                ['id' => $event->messageId, 'h' => 'award-points'],
